  &quot;ReleaseLabel&quot;: &quot;emr-5.34.0&quot;,
  &quot;Applications&quot;: [
    {
      &quot;Name&quot;: &quot;Spark&quot;
    }
  ],
  &quot;Instances&quot;: {
    &quot;InstanceGroups&quot;: [
      {
        &quot;Name&quot;: &quot;Primary node&quot;,
