    updated() {
    },
    beforeDestroy() {
    },
    destroyed() {
    },
    computed: {},
    components: {},
  }
&lt;/script&gt;

&lt;style lang=&quot;scss&quot; rel=&quot;stylesheet/scss&quot;&gt;
  .test-model {

  }
