    oauth2:
      enable: false
      provider:
        github:
          authorizationUri: &quot;&quot;
          redirectUri: &quot;&quot;
          clientId: &quot;&quot;
          clientSecret: &quot;&quot;
          tokenUri: &quot;&quot;
          userInfoUri: &quot;&quot;
          callbackUrl: &quot;&quot;
          iconUri: &quot;&quot;
          provider: github
        google:
          authorizationUri: &quot;&quot;
          redirectUri: &quot;&quot;
          clientId: &quot;&quot;
          clientSecret: &quot;&quot;
          tokenUri: &quot;&quot;
