Master-Server
curl --request GET &#x27;http://localhost:5679/actuator/health&#x27;

{&quot;status&quot;:&quot;UP&quot;,&quot;components&quot;:{&quot;db&quot;:{&quot;status&quot;:&quot;UP&quot;,&quot;details&quot;:{&quot;database&quot;:&quot;H2&quot;,&quot;validationQuery&quot;:&quot;isValid()&quot;}}}}

Worker-Server
curl --request GET &#x27;http://localhost:1235/actuator/health&#x27;

{&quot;status&quot;:&quot;UP&quot;,&quot;components&quot;:{&quot;db&quot;:{&quot;status&quot;:&quot;UP&quot;,&quot;details&quot;:{&quot;database&quot;:&quot;H2&quot;,&quot;validationQuery&quot;:&quot;isValid()&quot;}}}}

