        page.create(tenant);

        await().untilAsserted(() -&gt; assertThat(page.tenantList())
                .as(&quot;Tenant list should contain newly-created tenant&quot;)
                .extracting(WebElement::getText)
                .anyMatch(it -&gt; it.contains(tenant)));
    }

